def add_role_bonuses():
    for cat in CONTENT['categories']:
        if cat['id'] not in ('job','hobby'):
            continue
        cat['experience']='profession' if cat['id']=='job' else 'hobby'
        descriptions=PROFESSION_BONUSES if cat['id']=='job' else HOBBY_BONUSES
        new=[]
        for value in cat['items']:
            bonus, skill=descriptions[value]
            obj={'text':value,'bonus':bonus}
            if skill: obj['skill']=skill
            new.append(obj)
        cat['items']=new

add_role_bonuses()

def ensure_seed(db):
    pack = db.get(Pack, 'basic')
    if not pack:
        db.add(Pack(id='basic', title=CONTENT['title'], content=CONTENT, revision=6, is_builtin=True))
        db.commit()
        return
    if pack.is_builtin and (pack.revision or 1) < 6:
        pack.title = CONTENT['title']
        pack.content = CONTENT
        pack.revision = 6
        db.commit()
